// ============================================
// VALIDATION INPUT - RFC-014 Compatible
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (for tracing only, NO validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Extract data (image URL or base64) ---
const dataRaw = ctx.data || body.data;
const source = ctx.source || body.source || 'url';

// --- Extract API key ---
const mistralKey = body.mistral_api_key 
  || ctx.mistral_api_key 
  || body.plugin_context?.api_keys?.mistral 
  || ctx.plugin_context?.api_keys?.mistral;

// --- Extract execution mode ---
const executionMode = ctx.execution_mode || body.execution_mode || 'online';

// --- Validation ---
const hasData = !!dataRaw;
const hasMistralKey = !!mistralKey;

if (!hasData) errors.push('data (URL ou base64) requis');
if (!hasMistralKey) errors.push('mistral_api_key requis');

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

// --- Prepare image URL for Mistral ---
let imageUrl = '';
if (source === 'base64') {
  imageUrl = 'data:image/png;base64,' + dataRaw;
} else {
  imageUrl = dataRaw;
}

return {
  valid: true,
  imageUrl: imageUrl,
  data: dataRaw,
  source: source,
  mistralApiKey: mistralKey,
  executionMode: executionMode,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

