// ============================================
// FORMAT SUCCESS/ERROR RESPONSE - with _trace
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// --- Check for API error ---
if (statusCode >= 400 || input.error) {
  const errorMessage = data.message || data.error?.message || input.error?.message || 'Mistral API error';
  return {
    success: false,
    error: {
      code: 'OCR_API_ERROR',
      message: errorMessage,
      http_status: statusCode >= 400 ? statusCode : 500
    },
    _trace: {
      service_response: { error: errorMessage, http_status: statusCode },
      provider: 'mistral-ocr',
      model: 'pixtral-12b-2409',
      mode: 'error',
      latency_ms: Date.now() - startTime,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request
    },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  };
}

try {
  const content = data.choices?.[0]?.message?.content || '{}';

  // Try to extract JSON from the response
  let parsed;
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    parsed = { tables: [], table_count: 0 };
  }

  // Generate markdown representation
  let rawMarkdown = '';
  if (parsed.tables && parsed.tables.length > 0) {
    parsed.tables.forEach((table, idx) => {
      if (idx > 0) rawMarkdown += '\n\n';
      // Header
      if (table.headers && table.headers.length > 0) {
        rawMarkdown += '| ' + table.headers.join(' | ') + ' |\n';
        rawMarkdown += '|' + table.headers.map(() => '---').join('|') + '|\n';
      }
      // Rows
      if (table.rows) {
        table.rows.forEach(row => {
          rawMarkdown += '| ' + row.join(' | ') + ' |\n';
        });
      }
    });
  }

  return {
    success: true,
    data: {
      tables: parsed.tables || [],
      raw_markdown: rawMarkdown || null,
      table_count: parsed.table_count || parsed.tables?.length || 0
    },
    meta: {
      provider: 'mistral-ocr',
      model: 'pixtral-12b-2409',
      execution_mode: prevData.executionMode,
      usage: data.usage || {}
    },
    _trace: {
      service_response: {
        table_count: parsed.table_count || parsed.tables?.length || 0,
        has_markdown: !!rawMarkdown
      },
      provider: 'mistral-ocr',
      model: 'pixtral-12b-2409',
      mode: 'table-extraction',
      latency_ms: Date.now() - startTime,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request
    },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  };
} catch (e) {
  return {
    success: false,
    error: {
      code: 'PARSE_ERROR',
      message: 'Failed to parse OCR response: ' + e.message,
      http_status: 500
    },
    _trace: {
      service_response: { error: e.message },
      provider: 'mistral-ocr',
      model: 'pixtral-12b-2409',
      mode: 'error',
      latency_ms: Date.now() - startTime,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id,
      user_request: prevData.user_request
    },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  };
}

// ============================================
// BUILD VALIDATION ERROR - with _trace
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};
